    @Test
    public void testCapacityGrow()
    {
        RectangleFList list = new RectangleFList();
        msAssert.areEqual(0, list.getCapacity());

        list.add(G_MISSING_ITEM);
        int capacity = list.getCapacity();
        msAssert.less(list.getCount(), capacity);

        while (list.getCount() != capacity)
            list.add(G_MISSING_ITEM);

        msAssert.areEqual(list.getCount(), list.getCapacity());

        list.add(G_MISSING_ITEM);
        msAssert.less(list.getCount(), list.getCapacity());
    }

